  "source": "def _t_eval(target, _t, scope):\n    p = _T_PATHS[_t]\n    if p[0] is T:\n        c = target\n    elif p[0] is S:\n        c = scope\n    else:\n        raise ValueError('TType instance with invalid root object')\n    for i in range(1, len(p), 2):\n        op, arg = p[i], p[i+1]\n        if type(arg) in (Spec, TType, Literal):\n            arg = scope[glom](target, arg, scope)\n        if op == '.':\n            try:\n                c = getattr(c, arg)\n            except AttributeError as e:\n                raise PathAccessError(e, Path(_t), i // 2)\n        elif op == '[':\n            try:\n                c = c[arg]\n            except (KeyError, IndexError, TypeError) as e:\n                raise PathAccessError(e, Path(_t), i // 2)\n        elif op == 'P':\n            get = scope[TargetRegistry].get_handler('get', c, path=p[2:i+2:2])\n            try:\n                c = get(c, arg)\n            except Exception as e:\n                raise PathAccessError(e, Path(_t), i // 2)\n        elif op == '(':\n            args, kwargs = arg\n            scope[Path] += p[2:i+2:2]\n            c = scope[glom](target, Call(c, args, kwargs), scope)\n    return c"
